"""Развлекательная астрология: знак зодиака по дате рождения + краткий гороскоп.

Внимание: это исключительно развлекательный контент, не влияющий на медицинские
рекомендации. Знак вычисляется по дате, гороскоп — генерируется из шаблонов
локально, без внешних API.
"""
from __future__ import annotations

import datetime as dt
import random

_ZODIAC_DATES: list[tuple[str, int, int, int, int]] = [
    ("Козерог", 12, 22, 1, 19),
    ("Водолей", 1, 20, 2, 18),
    ("Рыбы", 2, 19, 3, 20),
    ("Овен", 3, 21, 4, 19),
    ("Телец", 4, 20, 5, 20),
    ("Близнецы", 5, 21, 6, 20),
    ("Рак", 6, 21, 7, 22),
    ("Лев", 7, 23, 8, 22),
    ("Дева", 8, 23, 9, 22),
    ("Весы", 9, 23, 10, 22),
    ("Скорпион", 10, 23, 11, 21),
    ("Стрелец", 11, 22, 12, 21),
]

_HOROSCOPE_TEMPLATES: list[str] = [
    "День благоприятен для общения и новых знакомств. Не забывайте пить достаточно воды.",
    "Стоит проявить осторожность в физических нагрузках. Слушайте своё тело.",
    "Хороший день для отдыха и восстановления сил. Ранний отбой рекомендован.",
    "Энергия на подъёме — отличный момент для прогулки на свежем воздухе.",
    "Возможна эмоциональная нестабильность. Дыхательные практики помогут сохранить спокойствие.",
    "День подходит для планирования. Структурируйте приёмы пищи по часам.",
    "Уделите внимание сну — сегодня он особенно важен для восстановления.",
    "Продуктивный день для умственной работы. Чередуйте активность с паузами.",
    "Прислушайтесь к интуиции в вопросах самочувствия. При сомнениях — к врачу.",
    "Благоприятный день для лёгкой физической активности и растяжки.",
]


def get_zodiac_sign(birth_date: str | None) -> str | None:
    """Знак зодиака по ISO-дате рождения (YYYY-MM-DD). None если дата невалидна."""
    if not birth_date:
        return None
    try:
        born = dt.date.fromisoformat(birth_date)
    except ValueError:
        return None
    month, day = born.month, born.day
    for name, m1, d1, m2, d2 in _ZODIAC_DATES:
        if (m1 == month and day >= d1) or (m2 == month and day <= d2):
            return name
    return None


def get_daily_horoscope(birth_date: str | None) -> str | None:
    """Развлекательный гороскоп: знак + детерминированный «прогноз» по дате дня.

    Сид генерируется из (знак + сегодняшний день) — один и тот же текст в течение дня.
    """
    sign = get_zodiac_sign(birth_date)
    if not sign:
        return None
    today = dt.date.today()
    seed = hash(f"{sign}:{today.isoformat()}") & 0xFFFFFFFF
    rng = random.Random(seed)
    template = rng.choice(_HOROSCOPE_TEMPLATES)
    return f"♈ {sign} (развлекательный гороскоп): {template}"
